(function(){'use strict';var button=document.getElementById('vertical-menu-btn'),menu=document.querySelector('.vertical-menu'),main=document.querySelector('.main-content'),header=document.querySelector('.navbar-header');if(!button||!menu)return;button.addEventListener('click',function(){if(window.innerWidth<992){menu.classList.toggle('open')}else{menu.classList.toggle('collapsed');main&&main.classList.toggle('collapsed');header&&header.classList.toggle('collapsed')}});document.querySelectorAll('.vertical-menu .has-arrow').forEach(function(link){link.addEventListener('click',function(e){e.preventDefault();var sub=link.nextElementSibling;if(sub)sub.classList.toggle('d-block')})})})();
